export const territoryById: Record<string, string> = Object.fromEntries(territories.map((t) => [t.id, t.title]))

const normalizeTerritory = (value: string) => value.trim().toLowerCase().replace(/\s*\(the\)$/, '').replace(/[^a-z0-9]/g, '')

export const territoryIdByName: Record<string, string> = Object.fromEntries(territories.map((t) => [normalizeTerritory(t.title), t.id]))

export function findTerritoryId(name: string): string | undefined {
  if (!name) return undefined
  const key = normalizeTerritory(name)
  return territoryIdByName[key] ?? territories.find((t) => normalizeTerritory(t.title) === key)?.id
}

